#stage { --ground:#2A1508; --main:#E9A23B; --second:#FFF3DC; --accent:#C2412A; color:var(--second); font-family:var(--sans, system-ui, sans-serif);
  --sky:color-mix(in srgb, var(--main) 72%, var(--accent)); --dusk:color-mix(in srgb, var(--accent) 50%, var(--ground)); --grass:color-mix(in srgb, var(--ground) 88%, var(--main)); --field:color-mix(in srgb, var(--main) 55%, var(--ground));
  --cloth:color-mix(in srgb, var(--main) 45%, var(--second)); --clothEdge:color-mix(in srgb, var(--accent) 60%, var(--ground)); --gold:color-mix(in srgb, var(--main) 88%, var(--second)); --goldDeep:color-mix(in srgb, var(--main) 65%, var(--accent));
  --red:var(--accent); --redDeep:color-mix(in srgb, var(--accent) 68%, var(--ground)); --skinR:color-mix(in srgb, var(--accent) 52%, var(--main)); --skinM:color-mix(in srgb, var(--main) 62%, var(--second)); --skinE:color-mix(in srgb, var(--main) 38%, var(--second));
  --lace:color-mix(in srgb, var(--second) 80%, var(--main)); --ink:var(--ground); --stone:color-mix(in srgb, var(--main) 30%, var(--ground)); --stoneLit:color-mix(in srgb, var(--main) 45%, var(--second)) }
.ground { position:absolute; inset:0; background:var(--ground) }
.words { position:absolute; margin:0; display:flex; flex-direction:column; gap:12px; align-items:center; text-align:center } .words > * { margin:0 }
.head-line { font-weight:800; font-size:64px; line-height:1.1; color:var(--second); text-shadow:0 0 8px var(--ground), 3px 3px 0 var(--ground), -2px -2px 0 var(--ground), 2px -2px 0 var(--ground), -2px 2px 0 var(--ground) }
.sub-line { font-weight:800; font-size:46px; line-height:1.25; color:var(--main); text-shadow:0 0 10px var(--ground), 3px 3px 0 var(--ground), -2px -2px 0 var(--ground), 2px -2px 0 var(--ground), -2px 2px 0 var(--ground) }
.sub-line span { display:inline-block }
.art { position:absolute; inset:0; width:100%; height:100%; overflow:visible }
.pip { position:absolute; left:81px; top:313px; width:918px; height:1027px; overflow:hidden; box-shadow:0 22px 50px rgba(0,0,0,.5); outline:4px solid color-mix(in srgb, var(--ground) 75%, var(--main)) }
.pip .art { overflow:hidden }
